-- 100: 横向合同签审、版本、合作方资质、收入认定和合同模板库。
-- 记录业务事实和待核验状态；不伪造签章、资质或财务认定回执。
BEGIN;

CREATE TABLE IF NOT EXISTS "横向合同版本" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "横向项目编号" integer NOT NULL REFERENCES "横向项目"("编号") ON DELETE CASCADE,
    "版本号" integer NOT NULL,
    "版本类型" varchar(30) NOT NULL DEFAULT '草稿',
    "文件路径" varchar(2000),
    "文件校验和" varchar(128),
    "变更摘要" varchar(2000),
    "签审状态" varchar(30) NOT NULL DEFAULT '待签审',
    "签审人编号" integer REFERENCES "人员"("编号"),
    "签审时间" timestamp without time zone,
    "创建人编号" integer NOT NULL REFERENCES "人员"("编号"),
    "创建时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "uq_横向合同版本_项目版本" UNIQUE ("横向项目编号", "版本号"),
    CONSTRAINT "ck_横向合同版本_版本" CHECK ("版本号" > 0),
    CONSTRAINT "ck_横向合同版本_状态" CHECK ("版本类型" IN ('草稿','正式','补充协议') AND "签审状态" IN ('待签审','签审中','已签审','退回','已作废'))
);
CREATE INDEX IF NOT EXISTS "ix_横向合同版本_项目" ON "横向合同版本" ("横向项目编号", "版本号" DESC);

CREATE TABLE IF NOT EXISTS "横向合作单位资质" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "横向项目编号" integer NOT NULL REFERENCES "横向项目"("编号") ON DELETE CASCADE,
    "单位名称" varchar(300) NOT NULL,
    "统一社会信用代码" varchar(50),
    "资质类型" varchar(100) NOT NULL,
    "资质编号" varchar(150),
    "有效期至" date,
    "核验状态" varchar(20) NOT NULL DEFAULT '待核验',
    "证明文件路径" varchar(2000),
    "核验人编号" integer REFERENCES "人员"("编号"),
    "核验时间" timestamp without time zone,
    "备注" varchar(1000),
    "创建人编号" integer NOT NULL REFERENCES "人员"("编号"),
    "创建时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "ck_横向合作单位资质_状态" CHECK ("核验状态" IN ('待核验','已通过','不通过','已过期'))
);
CREATE INDEX IF NOT EXISTS "ix_横向合作单位资质_项目状态" ON "横向合作单位资质" ("横向项目编号", "核验状态", "有效期至");

CREATE TABLE IF NOT EXISTS "横向合同收入认定" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "横向项目编号" integer NOT NULL REFERENCES "横向项目"("编号") ON DELETE CASCADE,
    "认定类型" varchar(50) NOT NULL DEFAULT '技术合同认定',
    "申请金额" numeric(18,2) NOT NULL DEFAULT 0,
    "认定金额" numeric(18,2),
    "认定编号" varchar(150),
    "状态" varchar(30) NOT NULL DEFAULT '待提交',
    "申请材料路径" varchar(2000),
    "回执路径" varchar(2000),
    "申请人编号" integer NOT NULL REFERENCES "人员"("编号"),
    "审核人编号" integer REFERENCES "人员"("编号"),
    "审核时间" timestamp without time zone,
    "备注" varchar(1000),
    "创建时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "更新时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "ck_横向合同收入认定_金额" CHECK ("申请金额" >= 0 AND ("认定金额" IS NULL OR "认定金额" >= 0)),
    CONSTRAINT "ck_横向合同收入认定_状态" CHECK ("状态" IN ('待提交','审核中','已认定','不通过','已撤回'))
);
CREATE INDEX IF NOT EXISTS "ix_横向合同收入认定_项目状态" ON "横向合同收入认定" ("横向项目编号", "状态", "创建时间" DESC);

CREATE TABLE IF NOT EXISTS "横向合同模板" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "模板编码" varchar(80) NOT NULL,
    "模板名称" varchar(200) NOT NULL,
    "合同类型" varchar(80) NOT NULL DEFAULT '产学研合同',
    "版本号" integer NOT NULL DEFAULT 1,
    "文件路径" varchar(2000),
    "文件校验和" varchar(128),
    "是否启用" boolean NOT NULL DEFAULT TRUE,
    "创建人编号" integer NOT NULL REFERENCES "人员"("编号"),
    "创建时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "更新时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "uq_横向合同模板_编码版本" UNIQUE ("模板编码", "版本号"),
    CONSTRAINT "ck_横向合同模板_版本" CHECK ("版本号" > 0)
);

INSERT INTO "权限" ("编号", "上级编号", "名称", "路径", "类型", "备注")
VALUES (211, 2, '横向合同治理', '科研办公/科研办公/横向合同治理.html', TRUE, '合同版本签审、合作方资质、收入认定和模板库')
ON CONFLICT ("编号") DO UPDATE SET "名称"=EXCLUDED."名称", "路径"=EXCLUDED."路径", "备注"=EXCLUDED."备注";
INSERT INTO "角色权限" ("角色编号", "权限编号")
SELECT r."编号", 211 FROM "角色" r
WHERE r."名称" IN ('系统管理员','科研管理员','科技办')
  AND NOT EXISTS (SELECT 1 FROM "角色权限" rp WHERE rp."角色编号"=r."编号" AND rp."权限编号"=211);

UPDATE "系统迁移版本"
SET "版本"=100, "脚本"='100_horizontal_contract_governance.sql',
    "检查摘要"='增加横向合同版本签审、合作方资质、收入认定和模板库', "应用时间"=CURRENT_TIMESTAMP
WHERE "编号"=1;
COMMIT;
